'use client';

import { FormEvent, useCallback, useEffect, useRef, useState } from 'react';
import { Brand } from './Brand';

type Category = 'web' | 'images' | 'news';
type Safe = 'off' | 'moderate' | 'strict';
type Region = 'ALL' | 'NG' | 'US' | 'GB' | 'CA' | 'GH' | 'ZA' | 'IN' | 'KE';
type Result = { title: string; url: string; displayUrl: string; description: string; thumbnail?: string | null; age?: string };
type Payload = {
  results: Result[];
  hasMore: boolean;
  provider: string;
  privacy: { providerReceivesQuery: boolean; queryStoredByBazaara: boolean; notice: string };
};
type ErrorPayload = { code: string; message: string };
const categories: { key: Category; label: string; icon: string }[] = [
  { key: 'web', label: 'Web', icon: 'globe' },
  { key: 'images', label: 'Images', icon: 'image' },
  { key: 'news', label: 'News', icon: 'news' },
];
const regions: { value: Region; label: string }[] = [
  { value: 'ALL', label: 'Worldwide' }, { value: 'NG', label: 'Nigeria' },
  { value: 'US', label: 'United States' }, { value: 'GB', label: 'United Kingdom' },
  { value: 'CA', label: 'Canada' }, { value: 'GH', label: 'Ghana' },
  { value: 'ZA', label: 'South Africa' }, { value: 'IN', label: 'India' }, { value: 'KE', label: 'Kenya' },
];
const icons: Record<string, React.ReactNode> = {
  search: <><circle cx="11" cy="11" r="7" /><path d="m16 16 5 5" /></>,
  globe: <><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" /></>,
  image: <><rect x="3" y="4" width="18" height="16" rx="3" /><circle cx="8" cy="9" r="1.5" /><path d="m3 17 5-5 4 4 3-3 6 6" /></>,
  news: <><rect x="4" y="4" width="16" height="16" rx="2" /><path d="M8 8h8M8 12h8M8 16h5" /></>,
  spark: <><path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z" /></>,
  map: <><path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15" /></>,
  shield: <><path d="m12 2 9 4v6c0 5-3 8-9 10-6-2-9-5-9-10V6l9-4Z" /><path d="m8.5 12 2.5 2.5 5-5" /></>,
  arrow: <><path d="M7 17 17 7M8 7h9v9" /></>,
  x: <><path d="M5 5 19 19M19 5 5 19" /></>,
  settings: <><circle cx="12" cy="12" r="3" /><path d="M12 2v4m0 12v4M2 12h4m12 0h4M5 5l3 3m8 8 3 3M19 5l-3 3m-8 8-3 3" /></>,
};
function Icon({ name, size = 20 }: { name: string; size?: number }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{icons[name]}</svg>;
}
function urlState() {
  if (typeof window === 'undefined') return { q: '', category: 'web' as Category, safe: 'moderate' as Safe, country: 'ALL' as Region };
  const p = new URLSearchParams(window.location.search);
  const category = p.get('category');
  const safe = p.get('safe');
  const country = p.get('country');
  return {
    q: (p.get('q') ?? '').slice(0, 200),
    category: categories.some((c) => c.key === category) ? category as Category : 'web' as Category,
    safe: ['off', 'moderate', 'strict'].includes(safe ?? '') ? safe as Safe : 'moderate' as Safe,
    country: regions.some((r) => r.value === country) ? country as Region : 'ALL' as Region,
  };
}

export function SearchExperience() {
  const [query, setQuery] = useState('');
  const [searched, setSearched] = useState('');
  const [category, setCategory] = useState<Category>('web');
  const [safe, setSafe] = useState<Safe>('moderate');
  const [country, setCountry] = useState<Region>('ALL');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<Payload | null>(null);
  const [error, setError] = useState<ErrorPayload | null>(null);
  const [loading, setLoading] = useState(false);
  const [showThumbnails, setShowThumbnails] = useState(false);
  const [filters, setFilters] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const runSearch = useCallback(async (next: { q: string; category: Category; safe: Safe; country: Region; page?: number }, updateUrl = true) => {
    const q = next.q.trim().replace(/\s+/g, ' ').slice(0, 200);
    const currentPage = next.page ?? 1;
    abortRef.current?.abort();
    if (!q) {
      setQuery(''); setSearched(''); setData(null); setError(null); setLoading(false);
      if (updateUrl) window.history.pushState(null, '', window.location.pathname);
      return;
    }
    const abort = new AbortController();
    abortRef.current = abort;
    setQuery(q); setSearched(q); setCategory(next.category); setSafe(next.safe); setCountry(next.country);
    setPage(currentPage); setData(null); setError(null); setLoading(true);
    const params = new URLSearchParams({ q, category: next.category, safe: next.safe, country: next.country, page: String(currentPage) });
    if (updateUrl) window.history.pushState(null, '', `?${params}`);
    try {
      const response = await fetch(`/api/search?${params}`, { signal: abort.signal, cache: 'no-store', headers: { Accept: 'application/json' } });
      const body = await response.json();
      if (abort.signal.aborted) return;
      if (!response.ok) {
        setError({ code: typeof body.code === 'string' ? body.code : 'SEARCH_FAILED', message: typeof body.message === 'string' ? body.message : 'Search could not be completed.' });
        return;
      }
      setData(body as Payload);
    } catch (caught) {
      if (abort.signal.aborted) return;
      setError({ code: 'NETWORK_ERROR', message: 'Unable to connect to Search. Check your connection and retry.' });
    } finally {
      if (!abort.signal.aborted) setLoading(false);
    }
  }, []);

  useEffect(() => {
    const sync = () => {
      const state = urlState();
      const p = new URLSearchParams(window.location.search);
      const requestedPage = Number(p.get('page') ?? '1');
      const nextPage = Number.isInteger(requestedPage) && requestedPage >= 1 && requestedPage <= 10 ? requestedPage : 1;
      setQuery(state.q);
      setCategory(state.category);
      setSafe(state.safe);
      setCountry(state.country);
      if (state.q) void runSearch({ ...state, page: state.category === 'images' ? 1 : nextPage }, false);
      else { abortRef.current?.abort(); setSearched(''); setLoading(false); setData(null); setError(null); }
    };
    sync();
    window.addEventListener('popstate', sync);
    return () => { window.removeEventListener('popstate', sync); abortRef.current?.abort(); };
  }, [runSearch]);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void runSearch({ q: query, category, safe, country });
  }
  function switchCategory(value: Category) {
    setCategory(value);
    if (searched) void runSearch({ q: searched, category: value, safe, country });
  }
  function changeSafe(value: Safe) {
    setSafe(value);
    if (searched) void runSearch({ q: searched, category, safe: value, country });
  }
  function changeCountry(value: Region) {
    setCountry(value);
    if (searched) void runSearch({ q: searched, category, safe, country: value });
  }
  const isHome = !searched;

  return <div className={`site ${isHome ? 'site-home' : 'site-results'}`}>
    <div className="ambient ambient-one" aria-hidden="true" /><div className="ambient ambient-two" aria-hidden="true" />
    <header className="topbar">
      <a href="/" className="logo-link" aria-label="BAZAARA Search home"><Brand compact={!isHome} /></a>
      <nav className="topnav" aria-label="Related Bazaara applications">
        <span className="topnav-current"><span className="active-pip" /> Ecosystem 3</span>
        <a href="http://localhost:3005" className="portal-link" title="Local BAZAARA platform home">Platform home <Icon name="arrow" size={15} /></a>
      </nav>
    </header>

    <main className={isHome ? 'main-home' : 'main-results'}>
      {isHome && <div className="hero-copy">
        <span className="eyebrow"><span className="eyebrow-line" /> INTRODUCING A DIFFERENT WAY TO DISCOVER</span>
        <h1>Every question<br /><span>starts somewhere.</span></h1>
        <p>Meet search designed with intention: clear results, useful context and choices you control.</p>
      </div>}
      <section className="search-section" aria-label="Search the web">
        <form className="search-form" onSubmit={submit} role="search">
          <Icon name="search" size={25} />
          <input ref={inputRef} aria-label="Search the web" name="q" enterKeyHint="search" autoComplete="off" spellCheck={false} placeholder="What are you curious about?" maxLength={200} value={query} onChange={(e) => setQuery(e.target.value)} />
          {query && <button type="button" aria-label="Clear search" className="clear-btn" onClick={() => { setQuery(''); inputRef.current?.focus(); }}><Icon name="x" size={18} /></button>}
          <button className="search-submit" type="submit" disabled={loading} aria-label="Submit search"><span>Search</span><Icon name="arrow" size={17} /></button>
        </form>
        <div className="search-tools">
          <div role="tablist" aria-label="Search category" className="category-tabs">
            {categories.map((item) => <button key={item.key} role="tab" aria-selected={category === item.key} className={`category-tab ${category === item.key ? 'selected' : ''}`} onClick={() => switchCategory(item.key)} type="button"><Icon name={item.icon} size={17} />{item.label}</button>)}
            <span className="separator" />
            <span className="category-future" title="Maps is planned, not yet available"><Icon name="map" size={17} /> Maps <span className="soon-dot" /></span>
            <span className="category-future" title="Bazaara AI is planned, not yet available"><Icon name="spark" size={17} /> AI <span className="soon-dot" /></span>
          </div>
          <button className={`filter-button ${filters ? 'filter-active' : ''}`} onClick={() => setFilters(!filters)} type="button" aria-expanded={filters} aria-controls="search-filters"><Icon name="settings" size={17} /> Filters</button>
        </div>
        {filters && <div className="filter-panel" id="search-filters">
          <label>SafeSearch <select value={safe} onChange={(e) => changeSafe(e.target.value as Safe)}><option value="strict">Strict</option><option value="moderate">Moderate</option><option value="off">Off</option></select></label>
          <label>Region <select value={country} onChange={(e) => changeCountry(e.target.value as Region)}>{regions.map((region) => <option key={region.value} value={region.value}>{region.label}</option>)}</select></label>
          {category === 'images' && <label className="check-field"><input type="checkbox" checked={showThumbnails} onChange={(e) => setShowThumbnails(e.target.checked)} /> Display remote thumbnails</label>}
          <p>Displaying thumbnails contacts third-party image hosts. They are off by default.</p>
        </div>}
      </section>

      {isHome && <div className="homepage-extras">
        <div className="privacy-callout"><span className="privacy-icon"><Icon name="shield" size={19} /></span><div><strong>Privacy is a choice, not a slogan.</strong><p>Bazaara doesn’t save your search queries in this alpha. Searches are processed by Brave Search, which has separate policies.</p></div></div>
        <div className="explore"><span>EXPLORE SOMETHING NEW</span><div className="suggestions">{['African technology', 'Climate innovation', 'Tomorrow’s cities'].map((term) => <button key={term} onClick={() => void runSearch({ q: term, category: 'web', safe, country })} type="button">{term}<Icon name="arrow" size={14} /></button>)}</div></div>
      </div>}

      {!isHome && <section className="results-section" aria-live="polite" aria-busy={loading}>
        <div className="results-meta"><span>{loading ? 'Finding useful results…' : error ? 'Search unavailable' : `${category === 'web' ? 'Web' : category === 'images' ? 'Image' : 'News'} results`}</span><span className="meta-quiet">{data ? `Via ${data.provider} · Page ${page}` : 'BAZAARA SEARCH / ALPHA'}</span></div>
        {loading && <div className="skeleton-stack" aria-label="Loading search results" role="status">{[0, 1, 2, 3].map((i) => <div className="skeleton-card" key={i}><span /><span /><span /></div>)}</div>}
        {!loading && error && <div className="state-panel"><div className="state-icon">!</div><h2>{error.code === 'PROVIDER_NOT_CONFIGURED' ? 'Connect a search provider' : 'We couldn’t complete that search'}</h2><p>{error.message}</p><button type="button" onClick={() => void runSearch({ q: searched, category, safe, country, page })}>Try again</button>{error.code === 'PROVIDER_NOT_CONFIGURED' && <small>Set BRAVE_SEARCH_API_KEY in your local Search API environment to enable real results.</small>}</div>}
        {!loading && data && data.results.length === 0 && <div className="state-panel"><Icon name="search" size={31} /><h2>No results found</h2><p>Try a broader search term or choose another category.</p></div>}
        {!loading && data && data.results.length > 0 && <>
          {category === 'images' && !showThumbnails && <div className="image-note"><Icon name="shield" size={18} /> Image previews are off to limit third-party requests. Enable them under Filters.</div>}
          <div className={category === 'images' ? 'image-results' : 'web-results'}>
            {data.results.map((item, index) => <article className={category === 'images' ? 'image-result' : 'web-result'} key={`${item.url}-${index}`}>
              {category === 'images' && <div className="thumbnail">
                {showThumbnails && item.thumbnail ? <img src={item.thumbnail} alt="" loading="lazy" referrerPolicy="no-referrer" /> : <Icon name="image" size={32} />}
              </div>}
              <div className="result-content"><div className="result-domain"><span className="domain-favicon">{item.displayUrl.slice(0, 1).toUpperCase()}</span><span>{item.displayUrl}</span>{item.age && <span>· {item.age}</span>}</div><a href={item.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer" className="result-title">{item.title}<Icon name="arrow" size={17} /></a><p>{item.description}</p></div>
            </article>)}
          </div>
          {data.hasMore && <div className="pagination"><button type="button" onClick={() => { void runSearch({ q: searched, category, safe, country, page: Math.max(1, page - 1) }); window.scrollTo({ top: 0, behavior: 'smooth' }); }} disabled={page === 1}>Previous</button><span>Page {page}</span><button type="button" disabled={page >= 10} onClick={() => { void runSearch({ q: searched, category, safe, country, page: page + 1 }); window.scrollTo({ top: 0, behavior: 'smooth' }); }}>Next page <Icon name="arrow" size={15} /></button></div>}
          <p className="provider-disclosure">{data.privacy.notice}</p>
        </>}
      </section>}
    </main>
    <footer className="footer"><span>© 2026 BAZAARA <span className="footer-divider">/</span> ECOSYSTEM THREE</span><div><span className="alpha-badge">ALPHA BUILD 01</span><span>Powered by the Bazaara platform</span></div></footer>
  </div>;
}
